const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"./generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel Tenant {\n  id                     String                  @id @default(cuid())\n  slug                   String                  @unique\n  name                   String\n  type                   TenantType              @default(CANDIDACY)\n  defaultMode            PoliticalOperationMode  @default(CAMPAIGN)\n  config                 Json?\n  parentTenantId         String?\n  parent                 Tenant?                 @relation(\"TenantHierarchy\", fields: [parentTenantId], references: [id])\n  children               Tenant[]                @relation(\"TenantHierarchy\")\n  createdAt              DateTime                @default(now())\n  updatedAt              DateTime                @updatedAt\n  settings               CampaignSettings?\n  users                  User[]\n  divisions              PoliticalDivision[]     @relation(\"TenantDivisions\")\n  voters                 Voter[]\n  finances               FinancialEntry[]\n  witnesses              WitnessReport[]\n  events                 CampaignEvent[]\n  pointLogs              PointLog[]\n  inventory              InventoryItem[]\n  inventoryMovements     InventoryMovement[]\n  consentRecords         ConsentRecord[]\n  consentNotices         ConsentNotice[]\n  issueCases             IssueCase[]\n  interactions           Interaction[]\n  tasks                  Task[]\n  commitments            Commitment[]\n  communicationApprovals CommunicationApproval[]\n  teamInvitations        TeamInvitation[]\n  auditEvents            AuditEvent[]\n  storedObjects          StoredObject[]\n  operationProfile       OperationProfile?\n  politicalProposals     PoliticalProposal[]\n  subscription           TenantSubscription?\n  electronicSignatures   ElectronicSignature[]\n}\n\nmodel CampaignSettings {\n  id                String   @id @default(cuid())\n  tenantId          String   @unique\n  maxTotalBudget    Decimal  @db.Decimal(15, 2)\n  maxPublicityLimit Decimal  @db.Decimal(15, 2)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n  tenant            Tenant   @relation(fields: [tenantId], references: [id])\n}\n\nmodel StoredObject {\n  id               String                @id @default(cuid())\n  tenantId         String\n  uploaderId       String\n  path             String                @unique @db.VarChar(512)\n  module           StorageObjectModule\n  contentType      String                @db.VarChar(150)\n  expectedSize     Int\n  actualSize       Int?\n  etag             String?               @db.VarChar(255)\n  status           StoredObjectStatus    @default(ISSUED)\n  expiresAt        DateTime\n  confirmedAt      DateTime?\n  consumedAt       DateTime?\n  consumedByType   String?               @db.VarChar(64)\n  consumedById     String?               @db.VarChar(128)\n  documentCategory DocumentCategory?\n  retentionPhase   RetentionPhase        @default(MANAGEMENT)\n  createdAt        DateTime              @default(now())\n  updatedAt        DateTime              @updatedAt\n  tenant           Tenant                @relation(fields: [tenantId], references: [id])\n  uploader         User                  @relation(\"StoredObjectUploader\", fields: [uploaderId, tenantId], references: [id, tenantId])\n  signatures       ElectronicSignature[]\n\n  @@unique([id, tenantId])\n  @@index([tenantId, status, expiresAt])\n  @@index([tenantId, uploaderId, createdAt])\n  @@index([tenantId, module, consumedAt])\n}\n\nmodel User {\n  id                           String                  @id @default(cuid())\n  email                        String                  @unique\n  password                     String\n  mustChangePassword           Boolean                 @default(false)\n  temporaryPasswordExpiresAt   DateTime?\n  name                         String\n  role                         Role                    @default(VOLUNTEER)\n  isActive                     Boolean                 @default(true)\n  documentId                   String?\n  phone                        String?\n  totpSecret                   String? /// Encrypted TOTP secret (null = MFA not enabled)\n  totpEnabledAt                DateTime? /// When MFA was enabled\n  points                       Int                     @default(0)\n  tenantId                     String\n  divisionId                   String?\n  createdAt                    DateTime                @default(now())\n  updatedAt                    DateTime                @updatedAt\n  tenant                       Tenant                  @relation(fields: [tenantId], references: [id])\n  division                     PoliticalDivision?      @relation(fields: [divisionId, tenantId], references: [id, tenantId])\n  financialEntriesReported     FinancialEntry[]        @relation(\"FinancialEntryReporter\")\n  financialEntriesReviewed     FinancialEntry[]        @relation(\"FinancialEntryReviewer\")\n  financialEntriesCneMarked    FinancialEntry[]        @relation(\"FinancialEntryCneMarker\")\n  registeredVoters             Voter[]                 @relation(\"Registrar\")\n  witnessReports               WitnessReport[]         @relation(\"WitnessReportReporter\")\n  witnessReportsReviewed       WitnessReport[]         @relation(\"WitnessReportReviewer\")\n  pointLogs                    PointLog[]\n  inventoryMoves               InventoryMovement[]\n  consentsCaptured             ConsentRecord[]         @relation(\"ConsentCapturedBy\")\n  consentNoticesCreated        ConsentNotice[]         @relation(\"ConsentNoticeCreatedBy\")\n  casesAssigned                IssueCase[]             @relation(\"CaseAssignee\")\n  casesCreated                 IssueCase[]             @relation(\"CaseCreatedBy\")\n  interactions                 Interaction[]           @relation(\"InteractionActor\")\n  tasksAssigned                Task[]                  @relation(\"TaskAssignee\")\n  tasksCreated                 Task[]                  @relation(\"TaskCreator\")\n  commitmentsOwned             Commitment[]            @relation(\"CommitmentOwner\")\n  communicationsRequested      CommunicationApproval[] @relation(\"CommunicationRequestedBy\")\n  communicationsDecided        CommunicationApproval[] @relation(\"CommunicationDecidedBy\")\n  invitationsSent              TeamInvitation[]        @relation(\"InvitationInviter\")\n  eventsResponsible            CampaignEvent[]         @relation(\"EventResponsible\")\n  auditEvents                  AuditEvent[]            @relation(\"AuditActor\")\n  storedObjects                StoredObject[]          @relation(\"StoredObjectUploader\")\n  operationProfilesResponsible OperationProfile[]      @relation(\"OperationProfileResponsible\")\n  operationProfilesCreated     OperationProfile[]      @relation(\"OperationProfileCreatedBy\")\n  operationProfilesUpdated     OperationProfile[]      @relation(\"OperationProfileUpdatedBy\")\n  proposalsOwned               PoliticalProposal[]     @relation(\"ProposalOwner\")\n  proposalsCreated             PoliticalProposal[]     @relation(\"ProposalCreatedBy\")\n  proposalsUpdated             PoliticalProposal[]     @relation(\"ProposalUpdatedBy\")\n  electronicSignatures         ElectronicSignature[]\n\n  @@unique([id, tenantId])\n  @@unique([documentId, tenantId])\n  @@index([tenantId, role])\n  @@index([tenantId, isActive, role])\n  @@index([tenantId, divisionId])\n}\n\n/// Invitacion de acceso de un solo uso. El token nunca se persiste en claro:\n/// solo se conserva su SHA-256 para comprobar la aceptacion.\nmodel TeamInvitation {\n  id          String    @id @default(cuid())\n  tenantId    String\n  email       String\n  role        Role\n  tokenHash   String    @unique\n  expiresAt   DateTime\n  acceptedAt  DateTime?\n  invitedById String\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  tenant      Tenant    @relation(fields: [tenantId], references: [id])\n  invitedBy   User      @relation(\"InvitationInviter\", fields: [invitedById, tenantId], references: [id, tenantId])\n\n  @@unique([id, tenantId])\n  @@index([tenantId, email, acceptedAt, expiresAt])\n  @@index([tenantId, invitedById, createdAt])\n}\n\nmodel PoliticalDivision {\n  id             String              @id @default(cuid())\n  code           String\n  name           String\n  type           DivisionType\n  parentId       String?\n  tenantId       String\n  expectedTables Int?\n  goal           Int? /// Meta de personas a registrar en este territorio\n  tenant         Tenant              @relation(\"TenantDivisions\", fields: [tenantId], references: [id])\n  parent         PoliticalDivision?  @relation(\"Hierarchy\", fields: [parentId, tenantId], references: [id, tenantId])\n  children       PoliticalDivision[] @relation(\"Hierarchy\")\n  users          User[]\n  voters         Voter[]             @relation(\"VoterPuesto\")\n  witnesses      WitnessReport[]\n  issueCases     IssueCase[]\n\n  @@unique([id, tenantId])\n  @@unique([tenantId, code, type])\n  @@index([tenantId, type])\n  @@index([tenantId, parentId])\n}\n\nmodel Voter {\n  id                String             @id @default(cuid())\n  documentId        String\n  firstName         String\n  lastName          String\n  phone             String?\n  email             String?\n  tenantId          String\n  puestoId          String?\n  mesa              Int?\n  registrarId       String\n  isSignatureValid  Boolean            @default(false)\n  signatureImageUrl String?\n  consentAccepted   Boolean            @default(false)\n  consentIp         String?\n  consentTimestamp  DateTime?\n  termsVersion      String?            @default(\"2026.1\")\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  tenant            Tenant             @relation(fields: [tenantId], references: [id])\n  puesto            PoliticalDivision? @relation(\"VoterPuesto\", fields: [puestoId, tenantId], references: [id, tenantId])\n  registrar         User               @relation(\"Registrar\", fields: [registrarId, tenantId], references: [id, tenantId])\n  consentRecords    ConsentRecord[]\n  issueCases        IssueCase[]\n  interactions      Interaction[]\n\n  @@unique([id, tenantId])\n  @@unique([documentId, tenantId])\n  @@index([tenantId, puestoId])\n  @@index([tenantId, registrarId])\n}\n\nmodel FinancialEntry {\n  id                 String        @id @default(cuid())\n  type               EntryType\n  amount             Decimal       @db.Decimal(15, 2)\n  date               DateTime\n  cneCode            CneCode\n  description        String\n  tenantId           String\n  vendorName         String\n  vendorTaxId        String\n  evidenceUrl        String?       @unique\n  reporterId         String\n  reviewedById       String?\n  reviewedAt         DateTime?\n  reviewReason       String?       @db.VarChar(500)\n  cneReportedById    String?\n  cneReportedAt      DateTime?\n  cneReportReference String?       @db.VarChar(120)\n  status             FinanceStatus @default(PENDING)\n  auditLog           Json?\n  createdAt          DateTime      @default(now())\n  tenant             Tenant        @relation(fields: [tenantId], references: [id])\n  reporter           User          @relation(\"FinancialEntryReporter\", fields: [reporterId, tenantId], references: [id, tenantId])\n  reviewedBy         User?         @relation(\"FinancialEntryReviewer\", fields: [reviewedById, tenantId], references: [id, tenantId])\n  cneReportedBy      User?         @relation(\"FinancialEntryCneMarker\", fields: [cneReportedById, tenantId], references: [id, tenantId])\n\n  @@unique([id, tenantId])\n  @@index([tenantId, type, date])\n  @@index([tenantId, status, date])\n  @@index([tenantId, reviewedById, reviewedAt])\n  @@index([tenantId, cneReportedById, cneReportedAt])\n  @@index([tenantId, cneCode])\n}\n\nmodel WitnessReport {\n  id                String              @id @default(cuid())\n  tenantId          String\n  witnessId         String\n  puestoId          String\n  mesa              Int\n  e14ImageUrl       String              @unique\n  candidateVotes    Int\n  totalTableVotes   Int\n  observations      String?\n  isSynced          Boolean             @default(false)\n  status            WitnessReportStatus @default(PENDING)\n  reviewerId        String?\n  reviewReason      String?             @db.VarChar(1000)\n  reviewedAt        DateTime?\n  supersededById    String?\n  createdAt         DateTime            @default(now())\n  updatedAt         DateTime            @updatedAt\n  tenant            Tenant              @relation(fields: [tenantId], references: [id])\n  puesto            PoliticalDivision   @relation(fields: [puestoId, tenantId], references: [id, tenantId])\n  witness           User                @relation(\"WitnessReportReporter\", fields: [witnessId, tenantId], references: [id, tenantId])\n  reviewer          User?               @relation(\"WitnessReportReviewer\", fields: [reviewerId, tenantId], references: [id, tenantId])\n  supersededBy      WitnessReport?      @relation(\"WitnessReportSupersession\", fields: [supersededById, tenantId], references: [id, tenantId])\n  supersededReports WitnessReport[]     @relation(\"WitnessReportSupersession\")\n\n  @@unique([id, tenantId])\n  @@index([tenantId, witnessId, createdAt])\n  @@index([tenantId, isSynced])\n  @@index([tenantId, status, createdAt])\n  @@index([tenantId, puestoId, mesa, status, createdAt])\n  @@index([tenantId, reviewerId, reviewedAt])\n  @@index([tenantId, supersededById])\n}\n\nmodel CampaignEvent {\n  id            String                 @id @default(cuid())\n  name          String\n  description   String?\n  startsAt      DateTime               @map(\"date\")\n  endsAt        DateTime\n  location      String?\n  status        CampaignEventStatus    @default(DRAFT)\n  capacity      Int?\n  responsibleId String?\n  mode          PoliticalOperationMode\n  points        Int                    @default(0)\n  tenantId      String\n  createdAt     DateTime               @default(now())\n  updatedAt     DateTime               @updatedAt\n  tenant        Tenant                 @relation(fields: [tenantId], references: [id])\n  responsible   User?                  @relation(\"EventResponsible\", fields: [responsibleId, tenantId], references: [id, tenantId])\n  attendees     PointLog[]\n\n  @@unique([id, tenantId])\n  @@index([tenantId, mode, startsAt])\n  @@index([tenantId, mode, status, startsAt])\n  @@index([tenantId, responsibleId, startsAt])\n}\n\nmodel PointLog {\n  id        String         @id @default(cuid())\n  tenantId  String\n  userId    String\n  amount    Int\n  reason    String\n  eventId   String?\n  createdAt DateTime       @default(now())\n  tenant    Tenant         @relation(fields: [tenantId], references: [id])\n  user      User           @relation(fields: [userId, tenantId], references: [id, tenantId])\n  event     CampaignEvent? @relation(fields: [eventId, tenantId], references: [id, tenantId])\n\n  @@index([tenantId, userId, createdAt])\n  @@index([tenantId, eventId])\n}\n\nmodel InventoryItem {\n  id        String              @id @default(cuid())\n  name      String\n  sku       String?\n  quantity  Int                 @default(0)\n  warehouse String?\n  tenantId  String\n  createdAt DateTime            @default(now())\n  updatedAt DateTime            @updatedAt\n  tenant    Tenant              @relation(fields: [tenantId], references: [id])\n  movements InventoryMovement[]\n\n  @@unique([id, tenantId])\n  @@unique([tenantId, sku])\n  @@index([tenantId, name])\n}\n\nmodel InventoryMovement {\n  id        String        @id @default(cuid())\n  tenantId  String\n  itemId    String\n  userId    String\n  quantity  Int\n  type      MovementType\n  reason    String?\n  createdAt DateTime      @default(now())\n  tenant    Tenant        @relation(fields: [tenantId], references: [id])\n  item      InventoryItem @relation(fields: [itemId, tenantId], references: [id, tenantId])\n  user      User          @relation(fields: [userId, tenantId], references: [id, tenantId])\n\n  @@index([tenantId, itemId, createdAt])\n  @@index([tenantId, userId, createdAt])\n}\n\n/// Historial versionado de autorizaciones de tratamiento de datos. No debe\n/// sobrescribirse al revocar: se agrega un nuevo evento y se conserva la prueba.\nmodel ConsentRecord {\n  id                String                   @id @default(cuid())\n  tenantId          String\n  mode              PoliticalOperationMode\n  subjectType       ConsentSubjectType\n  subjectRef        String\n  voterId           String?\n  purpose           ConsentPurpose\n  legalBasis        ConsentLegalBasis\n  status            ConsentStatus            @default(GRANTED)\n  collectionChannel ConsentCollectionChannel\n  noticeVersion     String\n  proofPath         String?\n  sourceIpHash      String?\n  capturedById      String?\n  grantedAt         DateTime\n  expiresAt         DateTime?\n  revokedAt         DateTime?\n  revocationReason  String?                  @db.VarChar(500)\n  createdAt         DateTime                 @default(now())\n  tenant            Tenant                   @relation(fields: [tenantId], references: [id])\n  voter             Voter?                   @relation(fields: [voterId, tenantId], references: [id, tenantId])\n  capturedBy        User?                    @relation(\"ConsentCapturedBy\", fields: [capturedById, tenantId], references: [id, tenantId])\n  interactions      Interaction[]\n\n  @@unique([id, tenantId])\n  @@index([tenantId, mode, subjectRef, purpose, status])\n  @@index([tenantId, voterId])\n  @@index([tenantId, expiresAt])\n}\n\n/// Versiones del aviso de privacidad configuradas por cada organización.\n/// Una versión retirada se conserva para poder reconstruir qué información\n/// recibió la persona al autorizar el tratamiento.\nmodel ConsentNotice {\n  id               String                 @id @default(cuid())\n  tenantId         String\n  mode             PoliticalOperationMode\n  purpose          ConsentPurpose\n  version          String                 @db.VarChar(32)\n  title            String                 @db.VarChar(160)\n  content          String                 @db.Text\n  controllerName   String                 @db.VarChar(200)\n  contactEmail     String                 @db.VarChar(254)\n  privacyPolicyUrl String?                @db.VarChar(2048)\n  isActive         Boolean                @default(true)\n  createdById      String\n  activatedAt      DateTime               @default(now())\n  retiredAt        DateTime?\n  createdAt        DateTime               @default(now())\n  tenant           Tenant                 @relation(fields: [tenantId], references: [id])\n  createdBy        User                   @relation(\"ConsentNoticeCreatedBy\", fields: [createdById, tenantId], references: [id, tenantId])\n\n  @@unique([id, tenantId])\n  @@unique([tenantId, mode, purpose, version])\n  @@index([tenantId, mode, purpose, isActive])\n  @@index([tenantId, createdById, createdAt])\n}\n\n/// Solicitud ciudadana, incidencia territorial o caso de campaña, con SLA y\n/// responsable explícitos. `mode` impide mezclar gestión pública y proselitismo.\nmodel IssueCase {\n  id                     String                  @id @default(cuid())\n  tenantId               String\n  mode                   PoliticalOperationMode\n  reference              String\n  title                  String\n  description            String\n  category               String\n  sourceChannel          CommunicationChannel\n  status                 IssueCaseStatus         @default(OPEN)\n  priority               WorkPriority            @default(MEDIUM)\n  voterId                String?\n  externalContactRef     String?\n  divisionId             String?\n  assigneeId             String?\n  createdById            String?\n  confidential           Boolean                 @default(false)\n  dueAt                  DateTime?\n  firstResponseAt        DateTime?\n  resolvedAt             DateTime?\n  createdAt              DateTime                @default(now())\n  updatedAt              DateTime                @updatedAt\n  tenant                 Tenant                  @relation(fields: [tenantId], references: [id])\n  voter                  Voter?                  @relation(fields: [voterId, tenantId], references: [id, tenantId])\n  division               PoliticalDivision?      @relation(fields: [divisionId, tenantId], references: [id, tenantId])\n  assignee               User?                   @relation(\"CaseAssignee\", fields: [assigneeId, tenantId], references: [id, tenantId])\n  createdBy              User?                   @relation(\"CaseCreatedBy\", fields: [createdById, tenantId], references: [id, tenantId])\n  interactions           Interaction[]\n  tasks                  Task[]\n  commitments            Commitment[]\n  communicationApprovals CommunicationApproval[]\n\n  @@unique([id, tenantId])\n  @@unique([tenantId, mode, reference])\n  @@index([tenantId, mode, status, priority])\n  @@index([tenantId, assigneeId, dueAt])\n  @@index([tenantId, voterId])\n  @@index([tenantId, divisionId])\n}\n\nmodel Interaction {\n  id                 String                 @id @default(cuid())\n  tenantId           String\n  mode               PoliticalOperationMode\n  issueCaseId        String?\n  voterId            String?\n  externalContactRef String?\n  actorId            String?\n  consentRecordId    String?\n  channel            CommunicationChannel\n  direction          InteractionDirection\n  summary            String\n  outcome            String?\n  sentiment          InteractionSentiment?\n  occurredAt         DateTime               @default(now())\n  createdAt          DateTime               @default(now())\n  tenant             Tenant                 @relation(fields: [tenantId], references: [id])\n  issueCase          IssueCase?             @relation(fields: [issueCaseId, tenantId], references: [id, tenantId])\n  voter              Voter?                 @relation(fields: [voterId, tenantId], references: [id, tenantId])\n  actor              User?                  @relation(\"InteractionActor\", fields: [actorId, tenantId], references: [id, tenantId])\n  consentRecord      ConsentRecord?         @relation(fields: [consentRecordId, tenantId], references: [id, tenantId])\n\n  @@index([tenantId, mode, occurredAt])\n  @@index([tenantId, issueCaseId, occurredAt])\n  @@index([tenantId, voterId, occurredAt])\n}\n\nmodel Task {\n  id           String                 @id @default(cuid())\n  tenantId     String\n  mode         PoliticalOperationMode\n  issueCaseId  String?\n  commitmentId String?\n  title        String\n  description  String?\n  status       TaskStatus             @default(TODO)\n  priority     WorkPriority           @default(MEDIUM)\n  assigneeId   String?\n  createdById  String\n  dueAt        DateTime?\n  completedAt  DateTime?\n  createdAt    DateTime               @default(now())\n  updatedAt    DateTime               @updatedAt\n  tenant       Tenant                 @relation(fields: [tenantId], references: [id])\n  issueCase    IssueCase?             @relation(fields: [issueCaseId, tenantId], references: [id, tenantId])\n  commitment   Commitment?            @relation(fields: [commitmentId, tenantId], references: [id, tenantId])\n  assignee     User?                  @relation(\"TaskAssignee\", fields: [assigneeId, tenantId], references: [id, tenantId])\n  createdBy    User                   @relation(\"TaskCreator\", fields: [createdById, tenantId], references: [id, tenantId])\n\n  @@index([tenantId, mode, status, dueAt])\n  @@index([tenantId, assigneeId, status])\n  @@index([tenantId, issueCaseId])\n  @@index([tenantId, commitmentId])\n}\n\n/// Promesa de campaña o compromiso de gobierno con seguimiento verificable.\nmodel Commitment {\n  id           String                 @id @default(cuid())\n  tenantId     String\n  mode         PoliticalOperationMode\n  reference    String\n  title        String\n  description  String\n  status       CommitmentStatus       @default(PROPOSED)\n  ownerId      String?\n  issueCaseId  String?\n  targetDate   DateTime?\n  progress     Int                    @default(0)\n  isPublic     Boolean                @default(false)\n  evidencePath String?\n  completedAt  DateTime?\n  createdAt    DateTime               @default(now())\n  updatedAt    DateTime               @updatedAt\n  tenant       Tenant                 @relation(fields: [tenantId], references: [id])\n  owner        User?                  @relation(\"CommitmentOwner\", fields: [ownerId, tenantId], references: [id, tenantId])\n  issueCase    IssueCase?             @relation(fields: [issueCaseId, tenantId], references: [id, tenantId])\n  tasks        Task[]\n\n  @@unique([id, tenantId])\n  @@unique([tenantId, reference])\n  @@index([tenantId, mode, status, targetDate])\n  @@index([tenantId, ownerId])\n}\n\n/// Flujo de cuatro ojos para mensajes públicos: el hash identifica exactamente\n/// la versión revisada y evita publicar una versión distinta a la aprobada.\nmodel CommunicationApproval {\n  id                    String                      @id @default(cuid())\n  tenantId              String\n  mode                  PoliticalOperationMode\n  issueCaseId           String?\n  channel               CommunicationChannel\n  title                 String\n  content               Json\n  contentHash           String\n  purpose               String\n  containsSensitiveData Boolean                     @default(false)\n  status                CommunicationApprovalStatus @default(PENDING)\n  requestedById         String\n  decidedById           String?\n  decisionReason        String?\n  scheduledAt           DateTime?\n  decidedAt             DateTime?\n  createdAt             DateTime                    @default(now())\n  updatedAt             DateTime                    @updatedAt\n  tenant                Tenant                      @relation(fields: [tenantId], references: [id])\n  issueCase             IssueCase?                  @relation(fields: [issueCaseId, tenantId], references: [id, tenantId])\n  requestedBy           User                        @relation(\"CommunicationRequestedBy\", fields: [requestedById, tenantId], references: [id, tenantId])\n  decidedBy             User?                       @relation(\"CommunicationDecidedBy\", fields: [decidedById, tenantId], references: [id, tenantId])\n\n  @@index([tenantId, mode, status, createdAt])\n  @@index([tenantId, scheduledAt])\n  @@index([tenantId, issueCaseId])\n}\n\n/// Registro append-only de operaciones sensibles. PostgreSQL rechaza UPDATE,\n/// DELETE y TRUNCATE; las capas de servicio redactan secretos antes de insertar.\nmodel AuditEvent {\n  id           String                 @id @default(cuid())\n  tenantId     String\n  mode         PoliticalOperationMode\n  actorType    AuditActorType\n  actorUserId  String?\n  action       String\n  resourceType String\n  resourceId   String?\n  outcome      AuditOutcome           @default(SUCCESS)\n  requestId    String?\n  sourceIpHash String?\n  userAgent    String?\n  before       Json?\n  after        Json?\n  metadata     Json?\n  occurredAt   DateTime               @default(now())\n  tenant       Tenant                 @relation(fields: [tenantId], references: [id])\n  actorUser    User?                  @relation(\"AuditActor\", fields: [actorUserId, tenantId], references: [id, tenantId])\n\n  @@index([tenantId, occurredAt])\n  @@index([tenantId, resourceType, resourceId, occurredAt])\n  @@index([tenantId, actorUserId, occurredAt])\n  @@index([tenantId, requestId])\n}\n\nenum TenantType {\n  CANDIDACY\n  PARTY\n  GSC\n  PUBLIC_OFFICE\n}\n\nenum PoliticalOperationMode {\n  CAMPAIGN\n  PUBLIC_OFFICE\n}\n\nenum Role {\n  ADMIN\n  CAMPAIGN_MANAGER\n  FINANCE_MANAGER\n  COMMUNICATIONS_MANAGER\n  CONSTITUENT_SERVICES_MANAGER\n  CASE_WORKER\n  COMPLIANCE_OFFICER\n  AUDITOR\n  ZONE_COORDINATOR\n  WITNESS\n  VOLUNTEER\n}\n\nenum DivisionType {\n  COUNTRY\n  DEPARTAMENTO\n  MUNICIPIO\n  ZONA\n  PUESTO\n}\n\nenum EntryType {\n  INCOME\n  EXPENSE\n}\n\nenum FinanceStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  REPORTED_CNE\n}\n\nenum WitnessReportStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  SUPERSEDED\n}\n\nenum MovementType {\n  IN\n  OUT\n  ADJUSTMENT\n}\n\nenum StorageObjectModule {\n  FINANCE\n  E14\n}\n\nenum StoredObjectStatus {\n  ISSUED\n  CONFIRMED\n  CONSUMED\n  EXPIRED\n}\n\nenum CneCode {\n  PUBLICIDAD_VALLAS\n  TRANSPORTE\n  SEDE_CAMPANA\n  ACTOS_PUBLICOS\n  OTROS\n}\n\nenum ConsentSubjectType {\n  VOTER\n  CITIZEN\n  VOLUNTEER\n  USER\n  OTHER\n}\n\nenum ConsentPurpose {\n  POLITICAL_COMMUNICATION\n  VOLUNTEER_MANAGEMENT\n  EVENT_MANAGEMENT\n  CONSTITUENT_CASE_MANAGEMENT\n  SERVICE_FOLLOW_UP\n  ANALYTICS\n}\n\nenum ConsentLegalBasis {\n  EXPLICIT_CONSENT\n  LEGAL_OBLIGATION\n  PUBLIC_TASK\n  CONTRACT\n}\n\nenum ConsentStatus {\n  GRANTED\n  REVOKED\n  EXPIRED\n  DENIED\n}\n\nenum ConsentCollectionChannel {\n  WEB_FORM\n  PAPER\n  PHONE\n  IN_PERSON\n  IMPORT\n}\n\nenum CommunicationChannel {\n  IN_PERSON\n  PHONE\n  SMS\n  WHATSAPP\n  EMAIL\n  SOCIAL_MEDIA\n  WEB\n  LETTER\n  INTERNAL\n}\n\nenum InteractionDirection {\n  INBOUND\n  OUTBOUND\n  INTERNAL\n}\n\nenum InteractionSentiment {\n  POSITIVE\n  NEUTRAL\n  NEGATIVE\n  MIXED\n  UNKNOWN\n}\n\nenum IssueCaseStatus {\n  OPEN\n  TRIAGED\n  IN_PROGRESS\n  WAITING_ON_CITIZEN\n  WAITING_ON_EXTERNAL_ENTITY\n  RESOLVED\n  CLOSED\n  CANCELLED\n}\n\nenum WorkPriority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum TaskStatus {\n  TODO\n  IN_PROGRESS\n  BLOCKED\n  DONE\n  CANCELLED\n}\n\nenum CampaignEventStatus {\n  DRAFT\n  SCHEDULED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\nenum CommitmentStatus {\n  PROPOSED\n  PLANNED\n  IN_PROGRESS\n  AT_RISK\n  FULFILLED\n  NOT_FULFILLED\n  CANCELLED\n}\n\nenum CommunicationApprovalStatus {\n  DRAFT\n  PENDING\n  APPROVED\n  REJECTED\n  SCHEDULED\n  PUBLISHED\n  CANCELLED\n}\n\nenum AuditActorType {\n  USER\n  SERVICE\n  SYSTEM\n  ANONYMOUS\n}\n\nenum AuditOutcome {\n  SUCCESS\n  DENIED\n  FAILURE\n}\n\n// ─── Operation Profile ──────────────────────────────────────────────────────\n\nmodel OperationProfile {\n  id                    String                       @id @default(cuid())\n  tenantId              String                       @unique\n  operationType         PoliticalOperationType\n  stage                 PoliticalOperationStage\n  electionType          ElectoralContestType\n  circumscriptionType   ElectoralCircumscriptionType\n  circumscriptionName   String                       @db.VarChar(160)\n  circumscriptionCode   String?                      @db.VarChar(64)\n  listType              CandidateListType?\n  electionDate          DateTime\n  expectedTeamSize      Int\n  candidateCount        Int                          @default(1)\n  dataControllerName    String                       @db.VarChar(200)\n  responsibleDataUserId String\n  retentionPeriodDays   Int\n  revocationProcedure   String                       @db.VarChar(2000)\n  createdById           String\n  updatedById           String\n  createdAt             DateTime                     @default(now())\n  updatedAt             DateTime                     @updatedAt\n  tenant                Tenant                       @relation(fields: [tenantId], references: [id])\n  responsibleDataUser   User                         @relation(\"OperationProfileResponsible\", fields: [responsibleDataUserId, tenantId], references: [id, tenantId])\n  createdBy             User                         @relation(\"OperationProfileCreatedBy\", fields: [createdById, tenantId], references: [id, tenantId])\n  updatedBy             User                         @relation(\"OperationProfileUpdatedBy\", fields: [updatedById, tenantId], references: [id, tenantId])\n\n  @@unique([id, tenantId])\n  @@index([tenantId, operationType, stage])\n  @@index([tenantId, electionDate])\n  @@index([tenantId, responsibleDataUserId])\n}\n\nenum PoliticalOperationType {\n  PRE_CANDIDACY\n  SINGLE_CANDIDACY\n  CORPORATION_CANDIDACY\n  PARTY_MOVEMENT\n  SIGNATURE_COMMITTEE\n  TERRITORIAL_TEAM\n}\n\nenum PoliticalOperationStage {\n  EXPLORATION\n  PRE_CAMPAIGN\n  SIGNATURE_COLLECTION\n  CAMPAIGN\n  ELECTION_PREPARATION\n  SIMULATION\n  ELECTION_DAY\n  POST_ELECTION\n  CLOSED\n}\n\nenum ElectoralContestType {\n  PRESIDENCY\n  GOVERNORSHIP\n  MAYORALTY\n  SENATE\n  HOUSE_OF_REPRESENTATIVES\n  DEPARTMENTAL_ASSEMBLY\n  MUNICIPAL_COUNCIL\n  LOCAL_ADMINISTRATIVE_BOARD\n  INTERNAL_ELECTION\n  OTHER\n}\n\nenum ElectoralCircumscriptionType {\n  NATIONAL\n  DEPARTMENTAL\n  MUNICIPAL\n  LOCAL\n  SPECIAL\n  INTERNAL\n}\n\nenum CandidateListType {\n  CLOSED\n  OPEN_PREFERENTIAL\n}\n\nmodel PoliticalProposal {\n  id              String           @id @default(cuid())\n  tenantId        String\n  referenceCode   String           @db.VarChar(20)\n  title           String           @db.VarChar(200)\n  description     String           @db.VarChar(2000)\n  category        ProposalCategory\n  targetGroup     String?          @db.VarChar(200)\n  status          ProposalStatus   @default(DRAFT)\n  progressPercent Int              @default(0)\n  isPublic        Boolean          @default(false)\n  territory       String?          @db.VarChar(200)\n  estimatedCost   Decimal?         @db.Decimal(15, 2)\n  sourceUrl       String?          @db.VarChar(500)\n  ownerId         String\n  createdById     String\n  updatedById     String\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n  tenant          Tenant           @relation(fields: [tenantId], references: [id])\n  owner           User             @relation(\"ProposalOwner\", fields: [ownerId, tenantId], references: [id, tenantId])\n  createdBy       User             @relation(\"ProposalCreatedBy\", fields: [createdById, tenantId], references: [id, tenantId])\n  updatedBy       User             @relation(\"ProposalUpdatedBy\", fields: [updatedById, tenantId], references: [id, tenantId])\n\n  @@unique([id, tenantId])\n  @@unique([referenceCode, tenantId])\n  @@index([tenantId, category, status])\n  @@index([tenantId, isPublic])\n}\n\nenum ProposalCategory {\n  EDUCATION\n  HEALTH\n  INFRASTRUCTURE\n  SECURITY\n  ECONOMY\n  ENVIRONMENT\n  CULTURE\n  SOCIAL\n  GOVERNANCE\n  OTHER\n}\n\nenum ProposalStatus {\n  DRAFT\n  PROPOSED\n  IN_PROGRESS\n  COMPLETED\n  WITHDRAWN\n}\n\nmodel SubscriptionPlan {\n  id              String               @id @default(cuid())\n  name            String               @db.VarChar(100)\n  code            PlanCode             @unique\n  description     String               @db.VarChar(500)\n  maxUsers        Int\n  maxVoters       Int\n  maxStorageMb    Int\n  includesExport  Boolean              @default(false)\n  includesImport  Boolean              @default(false)\n  includesMfa     Boolean              @default(false)\n  includesApi     Boolean              @default(false)\n  monthlyPriceCop Decimal              @db.Decimal(12, 2)\n  yearlyPriceCop  Decimal              @db.Decimal(12, 2)\n  isActive        Boolean              @default(true)\n  sortOrder       Int                  @default(0)\n  createdAt       DateTime             @default(now())\n  updatedAt       DateTime             @updatedAt\n  subscriptions   TenantSubscription[]\n}\n\nmodel TenantSubscription {\n  id                 String             @id @default(cuid())\n  tenantId           String             @unique\n  planId             String\n  status             SubscriptionStatus @default(TRIAL)\n  billingCycle       BillingCycle       @default(MONTHLY)\n  currentPeriodStart DateTime\n  currentPeriodEnd   DateTime\n  trialEndsAt        DateTime?\n  cancelledAt        DateTime?\n  createdAt          DateTime           @default(now())\n  updatedAt          DateTime           @updatedAt\n  tenant             Tenant             @relation(fields: [tenantId], references: [id])\n  plan               SubscriptionPlan   @relation(fields: [planId], references: [id])\n\n  @@index([tenantId, status])\n  @@index([planId])\n  @@index([currentPeriodEnd, status])\n}\n\nenum PlanCode {\n  FREE\n  STARTER\n  PROFESSIONAL\n  ENTERPRISE\n}\n\nenum SubscriptionStatus {\n  TRIAL\n  ACTIVE\n  PAST_DUE\n  CANCELLED\n  EXPIRED\n}\n\nenum BillingCycle {\n  MONTHLY\n  YEARLY\n}\n\nmodel ElectronicSignature {\n  id           String   @id @default(cuid())\n  tenantId     String\n  documentId   String\n  signerId     String\n  documentHash String   @db.VarChar(255)\n  ipAddress    String?  @db.VarChar(45)\n  signedAt     DateTime @default(now())\n\n  tenant   Tenant       @relation(fields: [tenantId], references: [id])\n  document StoredObject @relation(fields: [documentId, tenantId], references: [id, tenantId])\n  signer   User         @relation(fields: [signerId, tenantId], references: [id, tenantId])\n\n  @@index([tenantId, documentId])\n  @@index([tenantId, signerId])\n}\n\nenum DocumentCategory {\n  CONTRACT\n  ACT\n  RESOLUTION\n  MEMORANDUM\n  REPORT\n  FINANCIAL\n  OTHER\n}\n\nenum RetentionPhase {\n  MANAGEMENT\n  CENTRAL\n  HISTORICAL\n}\n"
}

